// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotEquals;

import org.junit.jupiter.api.Test;

/** Compatibility controls for an appended, equality-bearing optional provider context. */
class PackedProviderContextCompatibilityTest {

	@Test
	void everyExistingContextConstructorKeepsItsAbsentOptionalProviderDefault() {
		assertEquals(new PackedPlanCache.Context(1L, 2L, 3L, 4L, 5L, 6L, 7L, 0L, 0L, 0L),
				new PackedPlanCache.Context(1L, 2L, 3L, 4L, 5L, 6L, 7L));
		assertEquals(new PackedPlanCache.Context(1L, 2L, 3L, 4L, 5L, 6L, 7L, 8L, 0L, 0L),
				new PackedPlanCache.Context(1L, 2L, 3L, 4L, 5L, 6L, 7L, 8L));
		assertEquals(new PackedPlanCache.Context(1L, 2L, 3L, 4L, 5L, 6L, 7L, 8L, 9L, 0L),
				new PackedPlanCache.Context(1L, 2L, 3L, 4L, 5L, 6L, 7L, 8L, 9L));
		assertEquals(new PackedPlanCache.Context(1L, 2L, 3L, 4L, 5L, 6L, 7L, 8L, 9L, 10L),
				new PackedPlanCache.Context(1L, 2L, 3L, 4L, 5L, 6L, 7L, 8L, 9L, 10L));
	}

	@Test
	void existingScalarRoutingHashCollisionDoesNotBecomeContextEquality() {
		// Long.hashCode folds its two words; these distinct coordinates have the same record routing hash.
		var first = new PackedPlanCache.Context(0L, 2L, 3L, 4L, 5L, 6L, 7L, 8L, 9L, 10L);
		var collision = new PackedPlanCache.Context(0x0000000100000001L, 2L, 3L, 4L, 5L, 6L, 7L, 8L, 9L, 10L);
		assertEquals(first.hashCode(), collision.hashCode());
		assertNotEquals(first, collision);
		assertFalse(first.structurallyMatches(collision));
	}
}
